properties.Script_1:
// --------------------------------------------------------------------
// Actualizar el registro origen del formulario con la empresa en curso
// --------------------------------------------------------------------
var formulario   = theRoot.dataView();
var empresa      = theApp.globalVarToString("sygemat_corralon_dat/EMP_ID");
var registro_EMP = new VRegister(theRoot);
registro_EMP.setTable("sygemat_corralon_dat/EMP_M");
var registro_EMP_existe = registro_EMP.readRegister("ID", [empresa], VRegister.SearchThis);
if (registro_EMP_existe == true)
{
	formulario.setRegister(registro_EMP);
	formulario.updateControls();
}
